<?php
$available=(int)Db::scalar("SELECT COALESCE(SUM(quantity_g-reserved_g),0) FROM batches WHERE status='published'");$reserved=(int)Db::scalar("SELECT COALESCE(SUM(reserved_g),0) FROM batches");$delivered30=(int)Db::scalar("SELECT COALESCE(SUM(quantity_g),0) FROM orders WHERE status='delivered' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)");$committed=(int)Db::scalar("SELECT COALESCE(SUM(total),0) FROM orders WHERE status IN ('payment_review','paid','dispatching')");$pipeline=(int)Db::scalar("SELECT COALESCE(SUM(quantity_g),0) FROM supply_requests WHERE status IN ('new','scheduled')");$forecast=$delivered30+(int)Db::scalar("SELECT COALESCE(SUM(quantity_g),0) FROM orders WHERE status IN ('paid','dispatching')");
$materials=Db::all("SELECT m.name_ar,m.name_en,COALESCE(SUM(CASE WHEN b.status='published' THEN b.quantity_g-b.reserved_g ELSE 0 END),0) available_g,COALESCE(SUM(b.reserved_g),0) reserved_g FROM materials m LEFT JOIN batches b ON b.material_id=m.id WHERE m.slug IN ('rice-straw','wheat-straw','corn-residues','sugarcane-bagasse') GROUP BY m.id,m.name_ar,m.name_en ORDER BY FIELD(m.slug,'rice-straw','wheat-straw','corn-residues','sugarcane-bagasse')");$max=1;foreach($materials as $r){$max=max($max,(int)$r['available_g']);}
?>
<div class="analytics-head"><div><div class="eyebrow"><?= t('لوحة مستقلة لدعم قرار الإدارة','SEPARATE EXECUTIVE DECISION VIEW') ?></div><h2><?= t('الأداء والتوقع التشغيلي','Performance & operating forecast') ?></h2><p><?= t('خط أساس مبسط، فعلي، تباين وتوقع عند الإتمام. الأرقام التدريبية ليست وعوداً تجارية.','A simplified baseline, actuals, variance and estimate at completion. Training figures are not commercial commitments.') ?></p></div><span class="forecast-chip"><?= t('نافذة توقع: ٣٠ يوماً','Forecast window: 30 days') ?></span></div>
<div class="metric-grid analytics-metrics"><article class="metric-card"><small><?= t('المتاح الفعلي','Actual available') ?></small><strong><?= qty($available) ?></strong></article><article class="metric-card"><small><?= t('محجوز قيد التنفيذ','Reserved in execution') ?></small><strong><?= qty($reserved) ?></strong></article><article class="metric-card"><small><?= t('قيمة ملتزم بها','Committed value') ?></small><strong><?= money($committed) ?></strong></article><article class="metric-card"><small><?= t('توقع تسليم ٣٠ يوماً','30-day delivery forecast') ?></small><strong><?= qty($forecast) ?></strong></article></div>
<div class="admin-two-col"><article class="admin-card"><h2><?= t('توزيع القدرة المتاحة','Available capacity by category') ?></h2><div class="bar-chart"><?php foreach($materials as $r): ?><div><b><?= e(localized($r)) ?></b><span><i style="width:<?= round((int)$r['available_g']/$max*100,2) ?>%"></i></span><small><?= qty((int)$r['available_g']) ?></small></div><?php endforeach; ?></div></article><article class="admin-card"><h2><?= t('مؤشرات الرقابة','Control indicators') ?></h2><div class="executive-table"><div><span><?= t('فعلي التسليم — ٣٠ يوماً','Delivered actual — 30 days') ?></span><b><?= qty($delivered30) ?></b></div><div><span><?= t('خط توريد لم يُفحص','Uninspected supply pipeline') ?></span><b><?= qty($pipeline) ?></b></div><div><span><?= t('تباين التوقع عن الفعلي','Forecast variance to actual') ?></span><b><?= qty(max(0,$forecast-$delivered30)) ?></b></div></div><p class="caption"><?= t('التوقع حساب قاعدي: الفعلي خلال ٣٠ يوماً + الطلبات المدفوعة وقيد الشحن. لا يستخدم نموذج تعلم آلي.','Rule-based forecast: 30-day actuals plus paid and dispatching orders. No machine-learning model is used.') ?></p></article></div>
<article class="admin-card"><h2><?= t('بوابات القرار','Decision gates') ?></h2><ol class="tracking-list"><li><?= t('اعتماد الفحص قبل النشر','Inspection approval before publication') ?></li><li><?= t('مراجعة التحويل قبل تحرير التنفيذ','Transfer review before execution release') ?></li><li><?= t('تأكيد الاستلام قبل إثبات الالتزامات','Receipt confirmation before liability recognition') ?></li><li><?= t('مراجعة التباين والتوقع في الاجتماع التنفيذي','Variance and forecast review at the executive meeting') ?></li></ol></article>
